// Company name to domain mapping
const companyDomainMapping = {
  // Client name -> M365 tenant domain (used as CIPP tenantFilter)
  "Contoso Ltd": "contoso.onmicrosoft.com",
  "Fabrikam Inc": "fabrikam.onmicrosoft.com",
  "Northwind Traders": "northwindtraders.onmicrosoft.com"
};

// Function to normalize strings for better matching
function normalizeString(str) {
  if (!str) return '';
  return str
    .toString()
    .toLowerCase()
    .trim()
    .replace(/[^\w\s]/g, '') // Remove special characters
    .replace(/\s+/g, ' '); // Normalize whitespace
}

// Create normalized mapping for better matching
const normalizedMapping = {};
Object.keys(companyDomainMapping).forEach(company => {
  const normalizedKey = normalizeString(company);
  normalizedMapping[normalizedKey] = companyDomainMapping[company];
});

// Get input data
const inputData = $input.all();

// Process each input item
for (const item of inputData) {
  const data = item.json;

  // Get the "Client Name" field specifically
  const clientName = data["Client Name"];

  if (!clientName || clientName.trim() === '') {
    // No client name provided, return nothing
    continue;
  }

  // Clean and normalize the client name (handle leading/trailing spaces)
  const cleanClientName = clientName.trim();
  const normalizedInput = normalizeString(cleanClientName);

  let domain = null;
  let matchedCompany = null;

  // Try exact normalized match first
  for (const [originalCompany, companyDomain] of Object.entries(companyDomainMapping)) {
    const normalizedCompany = normalizeString(originalCompany);

    if (normalizedInput === normalizedCompany) {
      domain = companyDomain;
      matchedCompany = originalCompany;
      break;
    }
  }

  // If no exact match, try partial matching
  if (!domain) {
    for (const [originalCompany, companyDomain] of Object.entries(companyDomainMapping)) {
      const normalizedCompany = normalizeString(originalCompany);

      // Check if the input contains the company name or vice versa
      if (normalizedInput.includes(normalizedCompany) || normalizedCompany.includes(normalizedInput)) {
        domain = companyDomain;
        matchedCompany = originalCompany;
        break;
      }
    }
  }

  // If still no match, try fuzzy matching (removing common words)
  if (!domain) {
    const commonWords = ['inc', 'ltd', 'corp', 'corporation', 'company', 'co', 'llc', 'limited', 'plc', 'pc', 'cpa', 'cpas'];
    let cleanedInput = normalizedInput;

    // Remove common corporate suffixes
    commonWords.forEach(word => {
      cleanedInput = cleanedInput.replace(new RegExp(`\\b${word}\\b`, 'g'), '').trim();
    });

    for (const [originalCompany, companyDomain] of Object.entries(companyDomainMapping)) {
      const normalizedCompany = normalizeString(originalCompany);
      let cleanedCompany = normalizedCompany;

      commonWords.forEach(word => {
        cleanedCompany = cleanedCompany.replace(new RegExp(`\\b${word}\\b`, 'g'), '').trim();
      });

      if (cleanedInput === cleanedCompany || 
          cleanedInput.includes(cleanedCompany) || 
          cleanedCompany.includes(cleanedInput)) {
        domain = companyDomain;
        matchedCompany = originalCompany;
        break;
      }
    }
  }

  // Return only the domain if found
  if (domain) {
    return [{
      json: {
        domain: domain
      }
    }];
  }
}

// No match found, return empty result
return [];

/**
 * n8n Code node — merge MFA + license streams (Run Once for All Items)
 *
 * - Do NOT dedupe by displayName only (same name, two domains → two users).
 * - One canonical join key per identity: "user:" + lower(UPN || mail || RowKey@...).
 *   License rows often have mail but no UPN; MFA rows have UPN but no mail — same
 *   address must map to the SAME key (do not use separate "mail:" vs "upn:" prefixes).
 * - If a node outputs one item whose json is an array of users, rows are flattened.
 */

const allInputs = $input.all();

/** One object per user row (handles item.json = single row OR array of rows). */
const inputRows = [];
allInputs.forEach((item) => {
  const data = item.json;
  if (Array.isArray(data)) {
    data.forEach((row) => {
      if (row && typeof row === 'object') inputRows.push(row);
    });
  } else if (data && typeof data === 'object') {
    inputRows.push(data);
  }
});

console.log('Total input items:', allInputs.length, '— flattened rows:', inputRows.length);

let mfaData = [];
let licenseData = [];

inputRows.forEach((data) => {
  if (!data || typeof data !== 'object') return;

  // Prefer explicit shapes: license rows usually have assignedLicenses + displayName (camelCase).
  // MFA rows: MFARegistration / MFAMethods / DisplayName (Pascal) / UPN / ID
  const hasMfaSignal =
    Object.prototype.hasOwnProperty.call(data, 'MFARegistration') ||
    Object.prototype.hasOwnProperty.call(data, 'MFAMethods') ||
    Object.prototype.hasOwnProperty.call(data, 'PerUser') ||
    Object.prototype.hasOwnProperty.call(data, 'MFACapable');

  const hasLicenseSignal =
    Object.prototype.hasOwnProperty.call(data, 'assignedLicenses') ||
    (Object.prototype.hasOwnProperty.call(data, 'mail') &&
      (Object.prototype.hasOwnProperty.call(data, 'displayName') ||
        Object.prototype.hasOwnProperty.call(data, 'DisplayName')));

  // Rows can include BOTH MFA and license fields (single Graph-style item) — send to both lists
  // so licenseDataMap and mfaDataMap each get a chance to index the same identity.
  if (hasLicenseSignal) licenseData.push(data);
  if (hasMfaSignal) mfaData.push(data);

  if (!hasLicenseSignal && !hasMfaSignal) {
    if (
      Object.prototype.hasOwnProperty.call(data, 'DisplayName') ||
      Object.prototype.hasOwnProperty.call(data, 'UPN') ||
      Object.prototype.hasOwnProperty.call(data, 'userPrincipalName')
    ) {
      mfaData.push(data);
    } else {
      licenseData.push(data);
    }
  }
});

console.log('MFA Data count:', mfaData.length);
console.log('License Data count:', licenseData.length);
console.log('Sample MFA item:', mfaData[0]);
console.log('Sample License item:', licenseData[0]);

function hasValidEmail(email) {
  return email && email !== 'N/A' && email !== 'No data' && String(email).trim() !== '';
}

function normStr(v) {
  return String(v == null ? '' : v)
    .trim()
    .toLowerCase();
}

/**
 * Single namespace so license (mail-only) and MFA (UPN-only) rows join when they
 * are the same address (case-insensitive). RowKey is often the UPN in table exports.
 */
function stableUserKey(item) {
  if (!item || typeof item !== 'object') return '';
  const upnN = normStr(item.userPrincipalName || item.UPN || item.upn);
  const mailRaw = item.mail || item.Mail || item.email || item.Email;
  const mailN = hasValidEmail(mailRaw) ? normStr(mailRaw) : '';
  const rk = item.RowKey;
  const rkN =
    typeof rk === 'string' && rk.includes('@') && hasValidEmail(rk.trim())
      ? normStr(rk)
      : '';

  const primary = upnN || mailN || rkN;
  if (primary) return 'user:' + primary;

  const dn = normStr(item.displayName || item.DisplayName);
  if (dn) return 'nameonly:' + dn;

  const id = item.ID || item.id;
  if (id != null && String(id).trim()) return 'id:' + String(id).trim();

  return '';
}

function getDataScore(item) {
  let score = 0;
  const upn = item.userPrincipalName || item.UPN || item.upn;
  if (normStr(upn)) score += 15;
  if (hasValidEmail(item.mail || item.Mail || item.Email)) score += 10;
  const lic = item.assignedLicenses;
  if (lic && lic !== 'No Licenses Assigned' && lic !== 'Unassigned') score += 5;
  if (item.displayName || item.DisplayName) score += 1;
  return score;
}

function pickBetterDuplicate(existing, incoming) {
  const a = getDataScore(existing);
  const b = getDataScore(incoming);
  if (b > a) return incoming;
  if (b < a) return existing;
  const upnB = normStr(incoming.userPrincipalName || incoming.UPN || incoming.upn);
  if (upnB && !normStr(existing.userPrincipalName || existing.UPN || existing.upn)) return incoming;
  return existing;
}

const licenseDataMap = new Map();

licenseData.forEach((item) => {
  const key = stableUserKey(item);
  if (!key) {
    console.warn('License row skipped (no UPN/mail/id/displayName):', item);
    return;
  }
  const existing = licenseDataMap.get(key);
  if (!existing) {
    licenseDataMap.set(key, item);
  } else {
    const chosen = pickBetterDuplicate(existing, item);
    if (chosen !== existing) {
      console.log('License duplicate key', key, '— keeping higher-score row');
    }
    licenseDataMap.set(key, chosen);
  }
});

const mfaDataMap = new Map();

mfaData.forEach((item) => {
  const key = stableUserKey(item);
  if (!key) {
    const dn = item.DisplayName || item.displayName;
    if (!dn) {
      console.warn('MFA row skipped (no identity):', item);
      return;
    }
    const fallbackKey = 'nameonly:' + normStr(dn);
    const existing = mfaDataMap.get(fallbackKey);
    if (!existing) mfaDataMap.set(fallbackKey, item);
    else {
      const exMail = hasValidEmail(existing.Email || existing.mail || existing.Mail);
      const nwMail = hasValidEmail(item.Email || item.mail || item.Mail);
      if (nwMail && !exMail) mfaDataMap.set(fallbackKey, item);
    }
    return;
  }

  const existing = mfaDataMap.get(key);
  if (!existing) {
    mfaDataMap.set(key, item);
  } else {
    const exMail = hasValidEmail(existing.Email || existing.mail || existing.Mail);
    const nwMail = hasValidEmail(item.Email || item.mail || item.Mail);
    if (nwMail && !exMail) mfaDataMap.set(key, item);
  }
});

const allKeys = new Set(licenseDataMap.keys());

console.log('Unique identities after merge (canonical user: key):', allKeys.size);

function toBoolMfa(v) {
  if (v === true || v === 'true' || v === 'True' || v === 1 || v === '1') return true;
  if (v === false || v === 'false' || v === 'False' || v === 0 || v === '0') return false;
  if (typeof v === 'string') {
    const s = v.trim().toLowerCase();
    if (s === 'registered' || s === 'yes' || s === 'enabled') return true;
    if (s === 'unregistered' || s === 'disabled' || s === 'no' || s === '') return false;
  }
  return !!v;
}

const combinedResults = [];

allKeys.forEach((key) => {
  const licenseInfo = licenseDataMap.get(key) || {};
  const mfaInfo = mfaDataMap.get(key) || {};

  const displayName =
    licenseInfo.displayName ||
    licenseInfo.DisplayName ||
    mfaInfo.DisplayName ||
    mfaInfo.displayName ||
    '';

  const userPrincipalName =
    licenseInfo.userPrincipalName ||
    licenseInfo.UPN ||
    licenseInfo.upn ||
    mfaInfo.userPrincipalName ||
    mfaInfo.UPN ||
    mfaInfo.upn ||
    null;

  let mail =
    licenseInfo.mail ||
    mfaInfo.mail ||
    mfaInfo.Email ||
    mfaInfo.Mail ||
    null;
  if (!mail && userPrincipalName && String(userPrincipalName).includes('@')) {
    mail = userPrincipalName;
  }

  const assignedLicenses =
    licenseInfo.assignedLicenses != null ? licenseInfo.assignedLicenses : null;

  let mfaMethods = mfaInfo.MFAMethods;
  if (mfaMethods == null) mfaMethods = [];
  if (typeof mfaMethods === 'string') mfaMethods = [mfaMethods];

  const combinedItem = {
    displayName,
    userPrincipalName,
    mail,
    assignedLicenses,
    MFAEnabled: toBoolMfa(mfaInfo.MFARegistration),
    MFAMethods: mfaMethods,
  };

  combinedResults.push(combinedItem);
});

combinedResults.sort((a, b) =>
  String(a.displayName || '')
    .toLowerCase()
    .localeCompare(String(b.displayName || '').toLowerCase())
);

return [
  {
    json: {
      results: combinedResults,
      totalUsers: combinedResults.length,
      processedAt: new Date().toISOString(),
      debug: {
        mfaDataCount: mfaData.length,
        licenseDataCount: licenseData.length,
        totalInputs: allInputs.length,
        flattenedRowCount: inputRows.length,
        uniqueUsersAfterDedup: combinedResults.length,
        sampleMfaFields: mfaData[0] ? Object.keys(mfaData[0]) : [],
        sampleLicenseFields: licenseData[0] ? Object.keys(licenseData[0]) : [],
      },
    },
  },
];

// Outputs one item with all incoming items under json.items
const combined = items.map(i => i.json);
return [{ json: { items: combined } }];

// Input: $input.first().json.Results (Graph Secure Score response)
// Output: one summary item only

const payload = $input.first()?.json ?? {};
const results = Array.isArray(payload.Results) ? payload.Results : [];

if (results.length === 0) {
  return [{ json: { summary: true, message: 'Results array missing in input' } }];
}

const latest = results.reduce((acc, r) => {
  const a = acc?.createdDateTime ? new Date(acc.createdDateTime).getTime() : -Infinity;
  const b = r?.createdDateTime ? new Date(r.createdDateTime).getTime() : -Infinity;
  return b > a ? r : acc;
}, results[0]);

const currentScore = Number(latest?.currentScore) || 0;
const maxScore = Number(latest?.maxScore) || 0;
const tenantScorePercent = maxScore > 0
  ? Math.round((currentScore / maxScore) * 10000) / 100
  : null;

const comparatives = Array.isArray(latest?.averageComparativeScores)
  ? latest.averageComparativeScores
  : [];
const byBasis = (basis) =>
  comparatives.find((c) => (c?.basis || '').toLowerCase() === basis);
const comp = byBasis('totalseats') || byBasis('alltenants') || comparatives[0] || null;

let comparativePercent = null;
let comparativeBasis = null;
let comparativeSeatRange = null;

if (comp) {
  const sumScore =
    (Number(comp.appsScore) || 0) +
    (Number(comp.dataScore) || 0) +
    (Number(comp.deviceScore) || 0) +
    (Number(comp.identityScore) || 0) +
    (Number(comp.infrastructureScore) || 0);

  const sumMax =
    (Number(comp.appsScoreMax) || 0) +
    (Number(comp.dataScoreMax) || 0) +
    (Number(comp.deviceScoreMax) || 0) +
    (Number(comp.identityScoreMax) || 0) +
    (Number(comp.infrastructureScoreMax) || 0);

  comparativePercent = sumMax > 0
    ? Math.round((sumScore / sumMax) * 10000) / 100
    : null;

  comparativeBasis = comp.basis || null;

  if (comp.SeatSizeRangeLowerValue || comp.SeatSizeRangeUpperValue) {
    comparativeSeatRange = {
      lower: comp.SeatSizeRangeLowerValue || null,
      upper: comp.SeatSizeRangeUpperValue || null,
    };
  }
}

return [{
  json: {
    summary: true,
    tenantCurrentScore: currentScore,
    tenantMaxScore: maxScore,
    tenantScorePercent,
    comparativeBasis,
    comparativeSeatRange,
    comparativePercent,
  },
}];

// Get the input data
const inputData = $input.first().json;

// Handle both array wrapper and direct object
const items = Array.isArray(inputData) ? inputData : [inputData];

// Format date to DD/MM/YYYY
const formatDate = (dateStr) => {
  if (!dateStr || dateStr.startsWith("0001")) return null;
  const d = new Date(dateStr);
  if (isNaN(d)) return null;
  return `${String(d.getUTCDate()).padStart(2, "0")}/${String(d.getUTCMonth() + 1).padStart(2, "0")}/${d.getUTCFullYear()}`;
};

const consolidatedDevices = [];

for (const item of items) {
  const results = item?.Results ?? [];

  for (const device of results) {
    // Convert bytes to GB
    const toGB = (bytes) =>
      bytes > 0 ? parseFloat((bytes / 1073741824).toFixed(2)) : null;

    const totalGB = toGB(device.totalStorageSpaceInBytes);
    const freeGB = toGB(device.freeStorageSpaceInBytes);

    consolidatedDevices.push({
      // --- Identity ---
      deviceName: device.deviceName ?? null,
      serialNumber: device.serialNumber ?? null,

      // --- User ---
      userDisplayName: device.userDisplayName ?? null,
      userPrincipalName: device.userPrincipalName ?? null,

      // --- Device Info ---
      manufacturer: device.manufacturer ?? null,
      model: device.model ?? null,
      joinType: device.joinType ?? null,

      // --- Storage ---
      totalStorageGB: totalGB,
      freeStorageGB: freeGB,
      usedStorageGB:
        totalGB !== null && freeGB !== null
          ? parseFloat((totalGB - freeGB).toFixed(2))
          : null,
      storageUsedPercent:
        device.totalStorageSpaceInBytes > 0
          ? parseFloat(
              (
                ((device.totalStorageSpaceInBytes - device.freeStorageSpaceInBytes) /
                  device.totalStorageSpaceInBytes) *
                100
              ).toFixed(1)
            )
          : null,

      // --- Compliance & Security ---
      complianceState: device.complianceState ?? null,
      isEncrypted: device.isEncrypted ?? null,
      managementState: device.managementState ?? null,
      managementAgent: device.managementAgent ?? null,
      ownerType: device.ownerType ?? null,

      // --- Dates ---
      enrolledDate: formatDate(device.enrolledDateTime),
      lastSyncDate: formatDate(device.lastSyncDateTime),
    });
  }
}

return consolidatedDevices.map((device) => ({ json: device }));

const inputData = $input.first().json;
const items = Array.isArray(inputData) ? inputData : [inputData];

// Convert MB to the most readable unit
const formatStorage = (mb) => {
  if (!mb || isNaN(mb)) return null;
  const num = parseFloat(mb);
  if (num >= 1048576) return `${(num / 1048576).toFixed(2)} TB`;
  if (num >= 1024) return `${(num / 1024).toFixed(2)} GB`;
  return `${num.toFixed(0)} MB`;
};

const results = [];

for (const item of items) {
  const usedMB = parseFloat(item.GeoUsedStorageMB);
  const totalMB = parseFloat(item.TenantStorageMB);
  const freeMB = totalMB - usedMB;

  results.push({
    // --- Storage ---
    sharepointTotalStorage: formatStorage(totalMB),
    sharepointUsedStorage: formatStorage(usedMB),
    sharepointFreeStorage: formatStorage(freeMB),
    sharepointUsedPercent: `${item.Percentage}%`,
    sharepointStorageSummary: `${formatStorage(usedMB)} used of ${formatStorage(totalMB)}`,

    // --- Raw (for calculations downstream) ---
    sharepointTotalStorageMB: totalMB,
    sharepointUsedStorageMB: usedMB,
    sharepointFreeStorageMB: parseFloat(freeMB.toFixed(2)),
  });
}

return results.map((item) => ({ json: item }));

const inputItems = $input.all();

// Supports standard node output, arrays, and webhook bodies.
const containers = inputItems.flatMap((item) => {
  const value = item.json?.body ?? item.json;
  return Array.isArray(value) ? value : [value];
});

const emails = containers.flatMap((container) => {
  if (Array.isArray(container?.Results)) return container.Results;
  if (container?.SenderAddress) return [container];
  return [];
});

const totalBlockedByType = {};
const inboxTotals = {};

for (const email of emails) {
  const type = email.Type || 'Unknown';

  totalBlockedByType[type] =
    (totalBlockedByType[type] || 0) + 1;

  const recipients = Array.isArray(email.RecipientAddress)
    ? email.RecipientAddress
    : email.RecipientAddress
      ? [email.RecipientAddress]
      : [];

  // Count each recipient once per email.
  for (const recipient of new Set(recipients)) {
    const address = String(recipient).trim().toLowerCase();
    if (!address) continue;

    inboxTotals[address] ??= {
      email: address,
      totalBlocked: 0,
      blockedByType: {},
    };

    inboxTotals[address].totalBlocked += 1;
    inboxTotals[address].blockedByType[type] =
      (inboxTotals[address].blockedByType[type] || 0) + 1;
  }
}

const top5Inboxes = Object.values(inboxTotals)
  .sort(
    (a, b) =>
      b.totalBlocked - a.totalBlocked ||
      a.email.localeCompare(b.email)
  )
  .slice(0, 5);

return [{
  json: {
    top5Inboxes,
    totalBlockedByType,
    grandTotalBlocked: emails.length,
  },
}];

// Merge all incoming items into a single array under one item
const items = $input.all();

// Option 1: Wrap everything into one item with a "data" array
return [{
