// Qualifies for the Unlicensed Users with Sign-in Enabled section:
// - no assigned licenses (unlicensed)
// - accountEnabled === true (sign-in enabled)
// - userType !== 'Guest' (excludes external users)
// - displayName does not contain "break glass" (excludes emergency access accounts)
function qualifiesAsUnlicensedEnabled(user) {
  const isUnlicensed =
    !user.assignedLicenses ||
    !Array.isArray(user.assignedLicenses) ||
    user.assignedLicenses.length === 0;

  const isSignInEnabled = user.accountEnabled === true;

  const isNotGuest = user.userType !== 'Guest';

  const displayName = (user.displayName || '').toLowerCase();
  const isNotBreakGlass = !displayName.includes('break glass');

  return isUnlicensed && isSignInEnabled && isNotGuest && isNotBreakGlass;
}

// Get the input data
const inputData = $input.all();

// Array to store all processed results
const allProcessedData = [];

// Loop through all input items
for (let i = 0; i < inputData.length; i++) {
  const currentItem = inputData[i].json;

  if (Array.isArray(currentItem)) {
    const processedUsers = currentItem
      .filter(qualifiesAsUnlicensedEnabled)
      .map(user => ({
        displayName: user.displayName,
        userPrincipalName: user.userPrincipalName
      }));

    allProcessedData.push(...processedUsers);
  } else {
    if (qualifiesAsUnlicensedEnabled(currentItem)) {
      allProcessedData.push({
        displayName: currentItem.displayName,
        userPrincipalName: currentItem.userPrincipalName
      });
    }
  }
}
// Wrap as a single tagged item so the report generator can identify this
// list distinctly from the general M365 user roster it also receives.
return [{
  json: {
