// --- License name resolution: three-tier fallback, in priority order ---
// Tier 1 (above): hand-curated, instant, for the SKUs we see most often.
// Tier 2 (csvReferenceMap): Microsoft's full official product catalog, loaded
//         into the ms_license_reference Data Table by the separate annual
//         "License Reference Data - CSV Loader" workflow.
// Tier 3 (tenantSkuMap): live /subscribedSkus call for this tenant. Not a
//         friendly name (Microsoft's internal String ID, e.g. "SPB"), but
//         guarantees we never fall through to "Unknown License".

const subscribedSkusRaw = $('Get Subscribed SKUs').first()?.json;
const skuResults = Array.isArray(subscribedSkusRaw?.Results) ? subscribedSkusRaw.Results : [];
const tenantSkuMap = {};
for (const sku of skuResults) {
  if (sku?.skuId) tenantSkuMap[sku.skuId] = sku.skuPartNumber || null;
}

const csvRefRows = $('Get MS License Reference').all().map(i => i.json);
const csvReferenceMap = {};
for (const row of csvRefRows) {
  if (row?.skuId) csvReferenceMap[row.skuId] = row.productName || null;
}

// Function to convert SKU ID to product name
function convertSkuToProductName(skuId) {
  if (!skuId || skuId.trim() === '') {
    return "Unassigned";
  }
  if (licenseMapping[skuId]) return licenseMapping[skuId];
  if (csvReferenceMap[skuId]) return csvReferenceMap[skuId];
  if (tenantSkuMap[skuId]) return tenantSkuMap[skuId];
  return `Unknown License (${skuId})`;
}

// NEW: qualifies for the Licensed Users section
// - must have at least one assigned license
// - must not be an external/guest account
// - accountEnabled is intentionally NOT checked here, disabled but licensed users still show
function qualifiesAsLicensed(user) {
  const isLicensed =
    !!user.assignedLicenses &&
    Array.isArray(user.assignedLicenses) &&
    user.assignedLicenses.length > 0;

  const isNotGuest = user.userType !== 'Guest';

  return isLicensed && isNotGuest;
}

// Get the input data
const inputData = $input.all();

// Array to store all processed results
const allProcessedData = [];

// Loop through all input items
for (let i = 0; i < inputData.length; i++) {
  const currentItem = inputData[i].json;

  if (Array.isArray(currentItem)) {
    const processedUsers = currentItem
      .filter(qualifiesAsLicensed)   // drop unlicensed and guest users here
      .map(user => {
        const processedUser = {
          displayName: user.displayName,
          mail: user.mail
        };

        // Every remaining user here is confirmed licensed, so this
        // will always take the "has licenses" branch, kept for consistency
        // with your existing formatting logic.
        if (user.assignedLicenses && Array.isArray(user.assignedLicenses) && user.assignedLicenses.length > 0) {
          const productNames = user.assignedLicenses.map(license =>
            convertSkuToProductName(license.skuId)
          );
          processedUser.assignedLicenses = productNames.join(', ');
        } else {
          processedUser.assignedLicenses = "Unassigned";
        }

        return processedUser;
      });

    allProcessedData.push(...processedUsers);
  } else {
    if (qualifiesAsLicensed(currentItem)) {
      const processedUser = {
        displayName: currentItem.displayName,
        mail: currentItem.mail
      };

      if (currentItem.assignedLicenses && Array.isArray(currentItem.assignedLicenses) && currentItem.assignedLicenses.length > 0) {
        const productNames = currentItem.assignedLicenses.map(license =>
          convertSkuToProductName(license.skuId)
        );
        processedUser.assignedLicenses = productNames.join(', ');
      } else {
        processedUser.assignedLicenses = "Unassigned";
      }

      allProcessedData.push(processedUser);
    }
  }
}

return allProcessedData.map(user => ({ json: user }));

// Input (from Merge3, append mode — 2 items):
//   Item A: Get Admins response — roleManagement/directory/roleAssignments?$expand=principal
//   Item B: Get Role Definitions response — roleManagement/directory/roleDefinitions?$select=id,displayName
// Output: one row per { user, userPrincipalName, adminRole }

const items = $input.all().map(i => i.json);

// Surface upstream API failures distinctly instead of silently returning
// zero admins, which is indistinguishable from "this tenant has no admins".
for (const item of items) {
  if (item && item.error) {
    return [{
      json: {
        type: "admin_fetch_error",
        message: item.error.message || "Unknown error retrieving directory roles",
        status: item.error.status ?? null
      }
    }];
  }
}

// Unwrap CIPP's {Results: [...]} envelope, tolerating a bare array too.
function unwrap(item) {
  if (Array.isArray(item?.Results)) return item.Results;
  if (Array.isArray(item)) return item;
  return item ? [item] : [];
}

let assignments = [];
let definitions = [];

for (const item of items) {
  const rows = unwrap(item);
  for (const row of rows) {
    if (!row) continue;
    // Assignment rows carry principalId + roleDefinitionId.
    // Definition rows carry id + displayName, no principalId.
    if (row.principalId != null || row.roleDefinitionId != null) {
      assignments.push(row);
    } else if (row.id != null && row.displayName != null) {
      definitions.push(row);
    }
  }
}

const roleNameById = new Map();
for (const def of definitions) {
  if (def?.id) roleNameById.set(def.id, def.displayName || def.id);
}

const output = [];
const seen = new Set(); // dedupe user+role combos

for (const assignment of assignments) {
  const principal = assignment.principal;
  // Skip service principals / apps / groups - only keep real users
  if (!principal || principal["@odata.type"] !== "#microsoft.graph.user") {
    continue;
  }

  const roleName = roleNameById.get(assignment.roleDefinitionId) || assignment.roleDefinitionId || "Unknown Role";
  const userName = principal.displayName || principal.userPrincipalName || "Unknown User";
  const upn = principal.userPrincipalName || principal.mail || "";

  const key = `${upn}|${roleName}`;
  if (seen.has(key)) continue;
  seen.add(key);

  output.push({
    json: {
      user: userName,
      userPrincipalName: upn,
      adminRole: roleName
    }
  });
}

return output;

const skus = $input.first()?.json?.Results;
// Every tenant has at least one SKU; empty means a bad response, not "no Intune".
if (!Array.isArray(skus) || !skus.length) throw new Error('Get Subscribed SKUs returned no Results');

const ACTIVE = new Set(['Enabled', 'Warning']);
const INTUNE_PLAN = /^INTUNE_(A|A_VL|EDU)$/i;

const intuneSkus = skus
  .filter(s => ACTIVE.has(s.capabilityStatus) &&
    (s.servicePlans || []).some(p =>
      INTUNE_PLAN.test(p.servicePlanName || '') && p.provisioningStatus === 'Success'))
  .map(s => s.skuPartNumber);

return [{ json: { intuneApplicable: intuneSkus.length > 0, intuneSkus } }];
